chapter-b1-1-infinitiv-mit-zu-data.js:
listening: {
    // Speakers reuse the chapter's Story Dialogue pair. New, related situation — professionally scripted, not a copy of the Story Dialogue.
    dialogue: [
      { id: 'B1_001_L001', speaker: 'Timo', gender: 'male', voice: 'de-DE-Neural2-D', de: 'Renke, ehrlich — drei Wochen zelten? Ich glaube, ich würde das keinen Tag aushalten.', en: 'Renke, honestly — three weeks camping? I don\'t think I\'d last a single day.' },
      { id: 'B1_001_L002', speaker: 'Renke', gender: 'female', voice: 'de-DE-Neural2-F', de: 'Genau deshalb mache ich es! Ich habe einfach vergessen, wie schön es ist, nichts vorzuhaben.', en: 'That\'s exactly why I\'m doing it! I just forgot how nice it is to have nothing planned.' },
      { id: 'B1_001_L003', speaker: 'Timo', gender: 'male', voice: 'de-DE-Neural2-D', de: 'Und wenn es regnet?', en: 'And if it rains?' },
      { id: 'B1_001_L004', speaker: 'Renke', gender: 'female', voice: 'de-DE-Neural2-F', de: 'Dann höre ich auf zu jammern und lese ein Buch im Zelt. Klingt das nicht wunderbar?', en: 'Then I stop complaining and read a book in the tent. Doesn\'t that sound wonderful?' },
      { id: 'B1_001_L005', speaker: 'Timo', gender: 'male', voice: 'de-DE-Neural2-D', de: 'Ehrlich gesagt — ein bisschen schon.', en: 'Honestly — a little bit, yes.' }
    ],
    transcript: 'Renke, ehrlich — drei Wochen zelten? Ich glaube, ich würde das keinen Tag aushalten. Genau deshalb mache ich es! Ich habe einfach vergessen, wie schön es ist, nichts vorzuhaben. Und wenn es regnet? Dann höre ich auf zu jammern und lese ein Buch im Zelt. Klingt das nicht wunderbar? Ehrlich gesagt — ein bisschen schon.',
    translation: 'Renke, honestly — three weeks camping? I don\'t think I\'d last a single day. That\'s exactly why I\'m doing it! I just forgot how nice it is to have nothing planned. And if it rains? Then I stop complaining and read a book in the tent. Doesn\'t that sound wonderful? Honestly — a little bit, yes.',

chapter-b1-2-nebensaetze-weil-da-obwohl-:
listening: {
    // Speakers reuse the chapter's Story Dialogue pair. New, related situation — professionally scripted, not a copy of the Story Dialogue.
    dialogue: [
      { id: 'B1_002_L001', speaker: 'Timo', gender: 'male', voice: 'de-DE-Neural2-D', de: 'Kommst du morgen wirklich mit an den Strand, obwohl es nur zwölf Grad hat?', en: 'Are you really coming to the beach tomorrow, even though it\'s only twelve degrees?' },
      { id: 'B1_002_L002', speaker: 'Frauke', gender: 'female', voice: 'de-DE-Neural2-F', de: 'Ehrlich? Ich weiß noch nicht. Da es so kalt ist, habe ich eigentlich keine Lust mehr.', en: 'Honestly? I don\'t know yet. Since it\'s so cold, I don\'t really feel like it anymore.' },
      { id: 'B1_002_L003', speaker: 'Timo', gender: 'male', voice: 'de-DE-Neural2-D', de: 'Schade. Ich gehe trotzdem, weil ich diese Woche einfach mal raus muss.', en: 'Too bad. I\'m going anyway, because I really just need to get out this week.' },
      { id: 'B1_002_L004', speaker: 'Frauke', gender: 'female', voice: 'de-DE-Neural2-F', de: 'Na gut — wenn du mir versprichst, dass wir danach etwas Warmes trinken, komme ich doch mit.', en: 'Alright — if you promise we\'ll get something warm to drink afterwards, I\'ll come after all.' }
    ],
    transcript: 'Kommst du morgen wirklich mit an den Strand, obwohl es nur zwölf Grad hat? Ehrlich? Ich weiß noch nicht. Da es so kalt ist, habe ich eigentlich keine Lust mehr. Schade. Ich gehe trotzdem, weil ich diese Woche einfach mal raus muss. Na gut — wenn du mir versprichst, dass wir danach etwas Warmes trinken, komme ich doch mit.',
    translation: 'Are you really coming to the beach tomorrow, even though it\'s only twelve degrees? Honestly? I don\'t know yet. Since it\'s so cold, I don\'t really feel like it anymore. Too bad. I\'m going anyway, because I really just need to get out this week. Alright — if you promise we\'ll get something warm to drink afterwards, I\'ll come after all.',

chapter-b1-3-konjunktiv2-hoefliche-bitte:
listening: {
    // Speakers reuse the chapter's Story Dialogue pair. New, related situation — professionally scripted, not a copy of the Story Dialogue.
    dialogue: [
      { id: 'B1_003_L001', speaker: 'Timo', gender: 'male', voice: 'de-DE-Neural2-D', de: 'Entschuldigung, mein Display ist komplett schwarz — könnten Sie mal draufschauen?', en: 'Excuse me, my screen is completely black — could you take a look?' },
      { id: 'B1_003_L002', speaker: 'Frau Lorenzen', gender: 'female', voice: 'de-DE-Neural2-F', de: 'Klar, zeigen Sie mal her. Höppla, das sieht nach einem Wackelkontakt aus.', en: 'Sure, show me. Oops, that looks like a loose connection.' },
      { id: 'B1_003_L003', speaker: 'Timo', gender: 'male', voice: 'de-DE-Neural2-D', de: 'Oh nein. Wäre das teuer zu reparieren?', en: 'Oh no. Would that be expensive to repair?' },
      { id: 'B1_003_L004', speaker: 'Frau Lorenzen', gender: 'female', voice: 'de-DE-Neural2-F', de: 'Nein, gar nicht — würden Sie es fünf Minuten hier lassen? Dann schaffe ich das schnell.', en: 'No, not at all — would you leave it here for five minutes? Then I can fix it quickly.' },
      { id: 'B1_003_L005', speaker: 'Timo', gender: 'male', voice: 'de-DE-Neural2-D', de: 'Das wäre super, vielen Dank!', en: 'That would be great, thank you very much!' }
    ],
    transcript: 'Entschuldigung, mein Display ist komplett schwarz — könnten Sie mal draufschauen? Klar, zeigen Sie mal her. Höppla, das sieht nach einem Wackelkontakt aus. Oh nein. Wäre das teuer zu reparieren? Nein, gar nicht — würden Sie es fünf Minuten hier lassen? Dann schaffe ich das schnell. Das wäre super, vielen Dank!',
    translation: 'Excuse me, my screen is completely black — could you take a look? Sure, show me. Oops, that looks like a loose connection. Oh no. Would that be expensive to repair? No, not at all — would you leave it here for five minutes? Then I can fix it quickly. That would be great, thank you very much!',

chapter-b1-4-folgen-deshalb-so-dass-data:
listening: {
    // Speakers reuse the chapter's Story Dialogue pair. New, related situation — professionally scripted, not a copy of the Story Dialogue.
    dialogue: [
      { id: 'B1_004_L001', speaker: 'Franzi', gender: 'female', voice: 'de-DE-Neural2-F', de: 'Ich möchte dieses Kabel zurückgeben — es ist so kaputt, dass es gar nicht mehr lädt.', en: 'I\'d like to return this cable — it\'s so broken that it doesn\'t charge at all anymore.' },
      { id: 'B1_004_L002', speaker: 'Timo', gender: 'male', voice: 'de-DE-Neural2-D', de: 'Zeigen Sie mal … stimmt, hier ist es total durchgescheuert. Haben Sie noch den Kassenzettel?', en: 'Let me see … you\'re right, it\'s completely worn through here. Do you still have the receipt?' },
      { id: 'B1_004_L003', speaker: 'Franzi', gender: 'female', voice: 'de-DE-Neural2-F', de: 'Ja, hier. Ich bin so überrascht, dass es schon nach zwei Wochen kaputt ist.', en: 'Yes, here. I\'m so surprised it broke after just two weeks.' },
      { id: 'B1_004_L004', speaker: 'Timo', gender: 'male', voice: 'de-DE-Neural2-D', de: 'Verstehe ich, deshalb bekommen Sie sofort ein neues — ganz ohne Diskussion.', en: 'I understand, so you\'ll get a new one right away — no discussion needed.' }
    ],
    transcript: 'Ich möchte dieses Kabel zurückgeben — es ist so kaputt, dass es gar nicht mehr lädt. Zeigen Sie mal … stimmt, hier ist es total durchgescheuert. Haben Sie noch den Kassenzettel? Ja, hier. Ich bin so überrascht, dass es schon nach zwei Wochen kaputt ist. Verstehe ich, deshalb bekommen Sie sofort ein neues — ganz ohne Diskussion.',
    translation: 'I\'d like to return this cable — it\'s so broken that it doesn\'t charge at all anymore. Let me see … you\'re right, it\'s completely worn through here. Do you still have the receipt? Yes, here. I\'m so surprised it broke after just two weeks. I understand, so you\'ll get a new one right away — no discussion needed.',

chapter-b1-5-genitiv-wegen-trotz-waehren:
listening: {
    // Speakers reuse the chapter's Story Dialogue pair. New, related situation — professionally scripted, not a copy of the Story Dialogue.
    dialogue: [
      { id: 'B1_005_L001', speaker: 'Kerstin', gender: 'female', voice: 'de-DE-Neural2-F', de: 'Warum isst du eigentlich schon wieder keinen Käse, Timo?', en: 'Why aren\'t you eating any cheese again, Timo?' },
      { id: 'B1_005_L002', speaker: 'Timo', gender: 'male', voice: 'de-DE-Neural2-D', de: 'Wegen meiner Fitness — ich koche diese Woche komplett vegan, trotz meiner großen Liebe zu Camembert.', en: 'Because of my fitness — I\'m cooking completely vegan this week, despite my great love for Camembert.' },
      { id: 'B1_005_L003', speaker: 'Kerstin', gender: 'female', voice: 'de-DE-Neural2-F', de: 'Respekt! Und das schaffst du wirklich, während der ganzen Woche?', en: 'Respect! And you\'re really managing that, for the whole week?' },
      { id: 'B1_005_L004', speaker: 'Timo', gender: 'male', voice: 'de-DE-Neural2-D', de: 'Bis jetzt schon — aber frag mich noch mal am Freitagabend.', en: 'So far, yes — but ask me again on Friday evening.' }
    ],
    transcript: 'Warum isst du eigentlich schon wieder keinen Käse, Timo? Wegen meiner Fitness — ich koche diese Woche komplett vegan, trotz meiner großen Liebe zu Camembert. Respekt! Und das schaffst du wirklich, während der ganzen Woche? Bis jetzt schon — aber frag mich noch mal am Freitagabend.',
    translation: 'Why aren\'t you eating any cheese again, Timo? Because of my fitness — I\'m cooking completely vegan this week, despite my great love for Camembert. Respect! And you\'re really managing that, for the whole week? So far, yes — but ask me again on Friday evening.',

chapter-b1-6-goethe-mini-1-data.js:
listening: {
    // Speakers reuse the chapter's Story Dialogue pair. New, related situation — professionally scripted, not a copy of the Story Dialogue.
    dialogue: [
      { id: 'B1_006_L001', speaker: 'Meike', gender: 'female', voice: 'de-DE-Neural2-F', de: 'Timo, ich bin heute Abend so nervös wegen der Probeprüfung morgen.', en: 'Timo, I\'m so nervous tonight about the mock exam tomorrow.' },
      { id: 'B1_006_L002', speaker: 'Timo', gender: 'male', voice: 'de-DE-Neural2-D', de: 'Musst du gar nicht sein — da du so viel geübt hast, wird das bestimmt gut laufen.', en: 'You really don\'t need to be — since you\'ve practiced so much, it\'ll definitely go well.' },
      { id: 'B1_006_L003', speaker: 'Meike', gender: 'female', voice: 'de-DE-Neural2-F', de: 'Meinst du das ernst, obwohl ich letzte Woche noch alles durcheinander hatte?', en: 'Do you mean that seriously, even though last week I still had everything mixed up?' },
      { id: 'B1_006_L004', speaker: 'Timo', gender: 'male', voice: 'de-DE-Neural2-D', de: 'Total. Würde es dir helfen, wenn wir jetzt noch einmal kurz zusammen üben?', en: 'Totally. Would it help if we practiced together once more right now?' },
      { id: 'B1_006_L005', speaker: 'Meike', gender: 'female', voice: 'de-DE-Neural2-F', de: 'Ja, das wäre toll — danke, dass du dir die Zeit nimmst.', en: 'Yes, that would be great — thanks for taking the time.' }
    ],
    transcript: 'Timo, ich bin heute Abend so nervös wegen der Probeprüfung morgen. Musst du gar nicht sein — da du so viel geübt hast, wird das bestimmt gut laufen. Meinst du das ernst, obwohl ich letzte Woche noch alles durcheinander hatte? Total. Würde es dir helfen, wenn wir jetzt noch einmal kurz zusammen üben? Ja, das wäre toll — danke, dass du dir die Zeit nimmst.',
    translation: 'Timo, I\'m so nervous tonight about the mock exam tomorrow. You really don\'t need to be — since you\'ve practiced so much, it\'ll definitely go well. Do you mean that seriously, even though last week I still had everything mixed up? Totally. Would it help if we practiced together once more right now? Yes, that would be great — thanks for taking the time.',
